#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

// Ideia: binária na resposta D. Um valor D é alcançável sse o grafo de conflitos
// (aresta entre pares com distância manhattan > D) é bipartido.
// Basta testar bipartição usando apenas arestas de cada ponto para os 4 pontos
// extremos nas diagonais (argmax/argmin de x+y e x−y): para qualquer par em
// conflito via |Δ(x+y)|>D, a cadeia (p, M), (M, m), (m, q) com M=argmax u, m=argmin u
// existe no grafo e força cores opostas em qualquer 2-coloração; análogo para v=x−y.
// Logo a bipartição do grafo reduzido coincide com a do grafo completo.

static const int MAXN = 300005;

static int Xs[MAXN], Ys[MAXN];
static int extList[4];
static ll dE[4][MAXN];
static int par[MAXN], rnk[MAXN];
static unsigned char rel[MAXN];
static int n, extCnt;

static vector<char> inBuf;
static size_t inPos = 0;

static void readAllInput() {
    char tmp[1 << 16];
    size_t r;
    while ((r = fread(tmp, 1, sizeof(tmp), stdin)) > 0)
        inBuf.insert(inBuf.end(), tmp, tmp + r);
}

static inline int readInt() {
    const size_t L = inBuf.size();
    while (inPos < L && (inBuf[inPos] < '0' || inBuf[inPos] > '9')) ++inPos;
    int x = 0;
    while (inPos < L && inBuf[inPos] >= '0' && inBuf[inPos] <= '9') {
        x = x * 10 + (inBuf[inPos] - '0');
        ++inPos;
    }
    return x;
}

static int dsuFind(int x) {
    int stk[64];
    int top = 0, cur = x;
    while (true) {
        stk[top++] = cur;
        if (par[cur] == cur) break;
        cur = par[cur];
    }
    int root = cur, acc = 0;
    for (int i = top - 2; i >= 0; --i) {
        acc ^= (int)rel[stk[i]];
        rel[stk[i]] = (unsigned char)acc;
        par[stk[i]] = root;
    }
    return root;
}

// exige cores diferentes entre a e b; retorna false seiação ímpar detectada
static inline bool dsuDiff(int a, int b) {
    int ra = dsuFind(a), rb = dsuFind(b);
    if (ra == rb) return rel[a] != rel[b];
    int w = ((int)rel[a] ^ (int)rel[b] ^ 1) & 1;
    if (rnk[ra] < rnk[rb]) { par[ra] = rb; rel[ra] = (unsigned char)w; }
    else if (rnk[rb] < rnk[ra]) { par[rb] = ra; rel[rb] = (unsigned char)w; }
    else { par[rb] = ra; rel[rb] = (unsigned char)w; ++rnk[ra]; }
    return true;
}

static bool feasible(ll D) {
    for (int i = 1; i <= n; ++i) { par[i] = i; rel[i] = 0; rnk[i] = 0; }
    for (int k = 0; k < extCnt; ++k) {
        const ll *dv = dE[k];
        const int e = extList[k];
        for (int i = 1; i <= n; ++i)
            if (dv[i] > D && !dsuDiff(i, e)) return false;
    }
    return true;
}

int main() {
    readAllInput();
    n = readInt();
    for (int i = 1; i <= n; ++i) Xs[i] = readInt();
    for (int i = 1; i <= n; ++i) Ys[i] = readInt();

    int iM = 1, im = 1, iT = 1, iB = 1;
    ll maxU = LLONG_MIN, minU = LLONG_MAX, maxV = LLONG_MIN, minV = LLONG_MAX;
    for (int i = 1; i <= n; ++i) {
        ll u = (ll)Xs[i] + Ys[i];
        ll v = (ll)Xs[i] - Ys[i];
        if (u > maxU) { maxU = u; iM = i; }
        if (u < minU) { minU = u; im = i; }
        if (v > maxV) { maxV = v; iT = i; }
        if (v < minV) { minV = v; iB = i; }
    }

    int cand[4] = { iM, im, iT, iB };
    extCnt = 0;
    for (int t = 0; t < 4; ++t) {
        bool dup = false;
        for (int s = 0; s < extCnt; ++s) if (extList[s] == cand[t]) { dup = true; break; }
        if (!dup) extList[extCnt++] = cand[t];
    }

    for (int k = 0; k < extCnt; ++k) {
        int e = extList[k];
        int xe = Xs[e], ye = Ys[e];
        ll *dv = dE[k];
        for (int i = 1; i <= n; ++i) {
            int dx = Xs[i] - xe; if (dx < 0) dx = -dx;
            int dy = Ys[i] - ye; if (dy < 0) dy = -dy;
            dv[i] = (ll)dx + dy;
        }
    }

    ll lo = 0, hi = max(maxU - minU, maxV - minV);
    while (lo < hi) {
        ll mid = lo + ((hi - lo) >> 1);
        if (feasible(mid)) hi = mid; else lo = mid + 1;
    }
    printf("%lld\n", lo);
    return 0;
}
